CREATE TABLE ${primehrSchema}.ld_learning_need (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,employee_fingerprint VARCHAR(64) NOT NULL,source_type VARCHAR(50) NOT NULL,source_reference_id VARCHAR(100),source_version BIGINT,source_fingerprint VARCHAR(64),target_competency_id VARCHAR(36),target_competency_code VARCHAR(50),target_competency_name VARCHAR(200),development_objective VARCHAR(3000) NOT NULL,current_state VARCHAR(2000) NOT NULL,target_state VARCHAR(2000) NOT NULL,success_measure VARCHAR(2000) NOT NULL,target_date DATE,priority VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT ck_ld_need_source CHECK(source_type IN ('COMPETENCY_GAP_REFERRAL','PERFORMANCE_DEVELOPMENT_OUTCOME','ORGANIZATIONAL_NEED','SUPERVISOR_OBSERVATION','EMPLOYEE_CAREER_GOAL','STATUTORY_PROFESSIONAL_REQUIREMENT','OTHER')),CONSTRAINT ck_ld_need_priority CHECK(priority IN ('LOW','MEDIUM','HIGH','CRITICAL')),CONSTRAINT ck_ld_need_status CHECK(status IN ('OPEN','LINKED','CANCELLED')));
CREATE INDEX ix_ld_need_employee ON ${primehrSchema}.ld_learning_need(agency_id,employee_no,status,target_date);
CREATE TABLE ${primehrSchema}.ld_individual_plan (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,series_id VARCHAR(36) NOT NULL,plan_version INT NOT NULL,supersedes_id VARCHAR(36),employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,job_position_id BIGINT NOT NULL,plantilla_id BIGINT NOT NULL,employee_fingerprint VARCHAR(64) NOT NULL,business_unit_id BIGINT NOT NULL,business_unit_name VARCHAR(200) NOT NULL,area_id BIGINT NOT NULL,area_name VARCHAR(200) NOT NULL,organization_fingerprint VARCHAR(64) NOT NULL,planning_year INT NOT NULL,overall_goal VARCHAR(3000) NOT NULL,status VARCHAR(20) NOT NULL,content_revision INT NOT NULL,submitted_by VARCHAR(100),submitted_at DATETIMEOFFSET,approved_by VARCHAR(100),approved_at DATETIMEOFFSET,return_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_ld_idp_supersedes FOREIGN KEY(supersedes_id) REFERENCES ${primehrSchema}.ld_individual_plan(id),CONSTRAINT uk_ld_idp_series_version UNIQUE(agency_id,series_id,plan_version),CONSTRAINT ck_ld_idp_version CHECK(plan_version>=1 AND content_revision>=1),CONSTRAINT ck_ld_idp_year CHECK(planning_year BETWEEN 2000 AND 2200),CONSTRAINT ck_ld_idp_status CHECK(status IN ('DRAFT','SUBMITTED','RECOMMENDED','RETURNED','APPROVED','CANCELLED')));
CREATE INDEX ix_ld_idp_employee ON ${primehrSchema}.ld_individual_plan(agency_id,employee_no,planning_year,status);
CREATE TABLE ${primehrSchema}.ld_individual_plan_item (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,plan_id VARCHAR(36) NOT NULL,learning_need_id VARCHAR(36) NOT NULL,source_type VARCHAR(50) NOT NULL,source_reference_id VARCHAR(100),source_version BIGINT,source_fingerprint VARCHAR(64),target_competency_id VARCHAR(36),target_competency_code VARCHAR(50),target_competency_name VARCHAR(200),development_objective VARCHAR(3000) NOT NULL,current_state VARCHAR(2000) NOT NULL,target_state VARCHAR(2000) NOT NULL,intervention_category VARCHAR(50) NOT NULL,success_measure VARCHAR(2000) NOT NULL,target_date DATE NOT NULL,employee_commitment VARCHAR(2000) NOT NULL,supervisor_commitment VARCHAR(2000) NOT NULL,priority VARCHAR(20) NOT NULL,display_order INT NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_ld_idp_item_plan FOREIGN KEY(plan_id) REFERENCES ${primehrSchema}.ld_individual_plan(id),CONSTRAINT fk_ld_idp_item_need FOREIGN KEY(learning_need_id) REFERENCES ${primehrSchema}.ld_learning_need(id),CONSTRAINT uk_ld_idp_item_need UNIQUE(agency_id,plan_id,learning_need_id),CONSTRAINT ck_ld_idp_item_order CHECK(display_order>=1));
CREATE INDEX ix_ld_idp_item_order ON ${primehrSchema}.ld_individual_plan_item(agency_id,plan_id,display_order);
CREATE TABLE ${primehrSchema}.ld_referral_disposition (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,referral_id VARCHAR(36) NOT NULL,referral_version BIGINT NOT NULL,referral_fingerprint VARCHAR(64) NOT NULL,employee_no VARCHAR(100) NOT NULL,decision VARCHAR(20) NOT NULL,learning_need_id VARCHAR(36),linked_idp_item_id VARCHAR(36),decided_by VARCHAR(100) NOT NULL,decided_at DATETIMEOFFSET NOT NULL,reason VARCHAR(2000) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_ld_disposition_referral FOREIGN KEY(referral_id) REFERENCES ${primehrSchema}.prime_ld_referral(id),CONSTRAINT fk_ld_disposition_need FOREIGN KEY(learning_need_id) REFERENCES ${primehrSchema}.ld_learning_need(id),CONSTRAINT fk_ld_disposition_item FOREIGN KEY(linked_idp_item_id) REFERENCES ${primehrSchema}.ld_individual_plan_item(id),CONSTRAINT uk_ld_referral_disposition UNIQUE(agency_id,referral_id,referral_version),CONSTRAINT ck_ld_disposition_decision CHECK(decision IN ('ACCEPTED','RETURNED','DECLINED')),CONSTRAINT ck_ld_disposition_link CHECK((decision='ACCEPTED' AND learning_need_id IS NOT NULL) OR (decision IN ('RETURNED','DECLINED') AND learning_need_id IS NULL AND linked_idp_item_id IS NULL)));
CREATE TABLE ${primehrSchema}.ld_idp_route (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,plan_id VARCHAR(36) NOT NULL,route_revision INT NOT NULL,request_code VARCHAR(100) NOT NULL,business_unit_id BIGINT NOT NULL,route_fingerprint VARCHAR(64) NOT NULL,submitted_content_revision INT NOT NULL,current_level INT NOT NULL,status VARCHAR(20) NOT NULL,submitted_by VARCHAR(100) NOT NULL,submitted_at DATETIMEOFFSET NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_ld_idp_route_plan FOREIGN KEY(plan_id) REFERENCES ${primehrSchema}.ld_individual_plan(id),CONSTRAINT uk_ld_idp_route_revision UNIQUE(agency_id,plan_id,route_revision),CONSTRAINT ck_ld_idp_route_numbers CHECK(route_revision>=1 AND submitted_content_revision>=1 AND current_level>=1),CONSTRAINT ck_ld_idp_route_status CHECK(status IN ('ACTIVE','RETURNED','COMPLETED','CANCELLED','SUPERSEDED')));
CREATE INDEX ix_ld_idp_route_current ON ${primehrSchema}.ld_idp_route(agency_id,plan_id,status,route_revision);
CREATE TABLE ${primehrSchema}.ld_idp_route_step (id VARCHAR(36) NOT NULL PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,route_id VARCHAR(36) NOT NULL,route_level INT NOT NULL,action_type VARCHAR(20) NOT NULL,employee_id BIGINT NOT NULL,employee_no VARCHAR(100) NOT NULL,employee_name VARCHAR(300) NOT NULL,appointment_id BIGINT NOT NULL,participant_fingerprint VARCHAR(64) NOT NULL,organization_fingerprint VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL,decided_by VARCHAR(100),decided_at DATETIMEOFFSET,decision_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at DATETIMEOFFSET NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at DATETIMEOFFSET NOT NULL,CONSTRAINT fk_ld_idp_step_route FOREIGN KEY(route_id) REFERENCES ${primehrSchema}.ld_idp_route(id),CONSTRAINT uk_ld_idp_route_step UNIQUE(agency_id,route_id,route_level),CONSTRAINT ck_ld_idp_step_level CHECK(route_level>=1),CONSTRAINT ck_ld_idp_step_action CHECK(action_type IN ('RECOMMEND','APPROVE')),CONSTRAINT ck_ld_idp_step_status CHECK(status IN ('PENDING','CURRENT','RECOMMENDED','RETURNED','APPROVED','SKIPPED')));
CREATE INDEX ix_ld_idp_step_actor ON ${primehrSchema}.ld_idp_route_step(agency_id,employee_no,status);
